  IF EXISTS (SELECT 1 FROM public.user_products WHERE catalog_product_id = '21a94166-3813-4c0f-8912-508fb8f704f1')
       OR EXISTS (SELECT 1 FROM public.user_product_usage WHERE product_id = '21a94166-3813-4c0f-8912-508fb8f704f1')
       OR EXISTS (SELECT 1 FROM public.product_submissions WHERE approved_product_id = '21a94166-3813-4c0f-8912-508fb8f704f1')
