    RAISE EXCEPTION 'catalog completeness slice1: retired Midnight oil row acquired an owner or plan reference';
  END IF;

  PERFORM pg_catalog.set_config('chaarlie.slice1_mode', 'apply', true);
END;
$mode$;

-- F04: unlink the Neqi submission <-> usage pair while both still name 'oil' (composite FKs + link triggers).
DO $link_unlink$
DECLARE
  v_rows integer;
BEGIN
  IF pg_catalog.current_setting('chaarlie.slice1_mode', true) IS DISTINCT FROM 'apply' THEN
    RETURN;
  END IF;

  UPDATE public.product_submissions SET user_product_usage_id = NULL
  WHERE id = 'da654fc1-97de-4cdb-ae3f-e2b6e8694494'::uuid AND category IS NOT DISTINCT FROM 'oil' AND user_product_usage_id IS NOT DISTINCT FROM '9769d546-e985-49b2-9692-c3bd19f52fd2';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN RAISE EXCEPTION 'slice1 unlink product_submissions touched % rows', v_rows; END IF;
  UPDATE public.user_product_usage SET product_submission_id = NULL
  WHERE id = '9769d546-e985-49b2-9692-c3bd19f52fd2'::uuid AND category IS NOT DISTINCT FROM 'oil' AND product_submission_id IS NOT DISTINCT FROM 'da654fc1-97de-4cdb-ae3f-e2b6e8694494';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN RAISE EXCEPTION 'slice1 unlink user_product_usage touched % rows', v_rows; END IF;
END;
$link_unlink$;

