dlich ausspülen."}],"evidence":[{"sourceUrl":"https://www.johnfrieda.com/de-de/produkte/frizz-ease/wunder-reparatur/conditioner/","sourceType":"manufacturer","checkedAt":"2026-10-09"},{"sourceUrl":"https://www.dm.de/p/d/3123413/john-frieda-conditioner-frizz-ease-wunder-reparatur","sourceType":"retailer","checkedAt":"2026-10-09"}]}$json$::jsonb, $json${"schemaVersion":2,"contractKind":"product_pointer","scope":{"kind":"product","category":"conditioner","productId":"62ff4f08-3ff2-49f3-9e93-e6fd0f395a4d"},"sourceRole":"conditioner_rinse_out","role":"condition","applicationFamily":"standard_rinse_out_conditioning","facts":{"applicationState":"wet_hair","applicationArea":"hair_lengths_ends","rinse":"rinse_out","contactTime":{"kind":"range_seconds","minimumSeconds":60,"maximumSeconds":180},"amount":null,"heat":null,"conditionerPolicy":"not_applicable"},"workflowId":null,"requiredCompanionProductId":null,"runtimeBlockerCode":null,"exactSteps":[],"cautionCodes":[],"evidence":[{"sourceUrl":"https://www.johnfrieda.com/de-de/produkte/frizz-ease/wunder-reparatur/conditioner/","sourceType":"manufacturer","checkedAt":"2026-10-09"},{"sourceUrl":"https://www.dm.de/p/d/3123413/john-frieda-conditioner-frizz-ease-wunder-reparatur","sourceType":"retailer","checkedAt":"2026-10-09"}]}$json$::jsonb);

