  VALUES ('73dd1822-5741-4f7f-94fa-7c18a973c281'::uuid, 'ba326dab-99d8-4b82-a1c5-de9aee2578a4'::uuid, 'leave_in'::text, 'post_wash_leave_in'::text, NULL::jsonb, 'damp_leave_on'::text, NULL::text, 'lengths_ends'::text, NULL::integer, 'leave_in'::text, 'not_stated'::text, $json$[]$json$::jsonb, 'dm Deutschland, exakte GTIN 8006530085724 (Anwendung)'::text, 'https://www.dm.de/p/d/3135991/aussie-leave-in-haarserum-100-hours-hydration'::text, 'Nach deiner Duschroutine oder unterwegs anwenden. Für feines bis mittleres Haar 1 mal drücken. Für dickes Haar 2 mal drücken. In den Händen verreiben und beobachten, wie es sich in Flüssigkeit verwandelt. Auf feuchtem oder trockenem Haar auftragen. Kein Ausspülen notwendig'::text, $json${"schemaVersion":1,"protocolVersion":1,"locale":"de","guidanceKey":"product-leave-in-ba326dab-99d8-4b82-a1c5-de9aee2578a4-post-wash","scope":{"kind":"product","category":"leave_in","productId":"ba326dab-99d8-4b82-a1c5-de9aee2578a4"},"role":"leave_in","applicationFamily":"post_wash_damp_conditioning","compatibleDayTypes":["wash_day","intensive_care_day","styling_day"],"exactGuidanceRequired":true,"sequence":{"anchor":"damp_leave_on","before":[],"after":["post_rinse_towel_dry"],"conflictsWith":[]},"requirements":{"requiredCatalogFacts":[],"requiredProtocolFacts":[],"requiredProfileFacts":[]},"protocolFacts":{"applicationArea":"lengths_ends","rinse":"leave_in","contactTimeSeconds":null,"conditionerRelationship":"not_applicable","reapplication":"none","amount":null,"cautions":[]},"steps":[{"stepKey":"towel-dry","action":"section","copyTemplateDe":"Das Haar nach dem Waschen mit dem Handtuch sanft ausdrücken, nicht rubbeln – nasses Haar bricht leichter."},{"stepKey":"apply","action":"apply_product","copyTemplateDe":"Eine kleine Menge in den Handflächen verreiben und in Längen und Spitzen einarbeiten, den Ansatz aussparen. Zum Verteilen mit einem grobzinkigen Kamm durchkämmen. Nicht ausspülen."}],"evidence":[{"sourceUrl":"https://www.dm.de/p/d/3135991/aussie-leave-in-haarserum-100-hours-hydration","sourceType":"retailer","checkedAt":"2026-10-09"}]}$json$::jsonb, $json${"schemaVersion":2,"contractKind":"product_pointer","scope":{"kind":"product","category":"leave_in","productId":"ba326dab-99d8-4b82-a1c5-de9aee2578a4"},"sourceRole":"post_wash_leave_in","role":"leave_in","applicationFamily":"post_wash_damp_conditioning","facts":{"applicationState":"damp_hair","applicationArea":"hair_lengths_ends","rinse":"leave_in","contactTime":null,"amount":null,"heat":null,"conditionerPolicy":"not_applicable"},"workflowId":null,"requiredCompanionProductId":null,"runtimeBlockerCode":null,"exactSteps":[],"cautionCodes":[],"evidence":[{"sourceUrl":"https://www.dm.de/p/d/3135991/aussie-leave-in-haarserum-100-hours-hydration","sourceType":"retailer","checkedAt":"2026-10-09"}]}$json$::jsonb);

